def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n >= 15:
        for p in (5, 6, 4, 3):
            if n < 2 * p:
                continue
            ok = True
            for i in range(n - p, n):
                if opp[i] != opp[i - p]:
                    ok = False
                    break
            if ok:
                d_count = 0
                for x in opp[-p:]:
                    if x == 'D':
                        d_count += 1
                if p == 5 and d_count == 2:
                    mism = 0
                    cnt = 0
                    for i in range(n - p, n):
                        if i > 0:
                            cnt += 1
                            if opp[i] != me[i - 1]:
                                mism += 1
                    if cnt > 0 and mism * 10 >= cnt * 4:
                        return 'D'

    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1

    opp_coop_rate = (n - opp_def) / n
    last_m = me[-1]
    last_o = opp[-1]

    if n < 10:
        return 'C' if last_o == 'C' else 'D'

    if n < 30:
        if opp_coop_rate > 0.7:
            return 'C'
        if opp_coop_rate < 0.3:
            return 'D'
        return 'C' if last_o == 'C' else 'D'

    recent = opp[-15:]
    recent_opp_coop = 0
    for x in recent:
        if x == 'C':
            recent_opp_coop += 1
    recent_opp_coop /= len(recent)

    recent5_oppD = 0
    for x in opp[-5:]:
        if x == 'D':
            recent5_oppD += 1

    if recent_opp_coop < 0.25:
        return 'D'

    if opp_coop_rate > 0.85 and recent_opp_coop > 0.85:
        return 'C'

    if last_o == 'D':
        if recent5_oppD >= 2:
            return 'D'
        if opp_coop_rate > 0.75 and recent_opp_coop > 0.65:
            return 'C'
        if n >= 95:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if n >= 95:
        return 'D' if recent_opp_coop < 0.9 else 'C'

    if recent_opp_coop < 0.5:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    if last_m == 'D':
        punished_recently = False
        start = max(1, n - 20)
        for i in range(start, n - 1):
            if me[i] == 'D' and opp[i + 1] == 'C':
                if i + 2 < n and opp[i + 2] == 'D':
                    punished_recently = True
                    break
        if not punished_recently:
            if recent_opp_coop > 0.9 and rng.random() < 0.5:
                return 'D'
            if recent_opp_coop > 0.7 and rng.random() < 0.2:
                return 'D'
        return 'C'

    return 'C'
